create function public.b06_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'B06 FAIL: %',label;end if;end;$$;
create function public.b06_reject(command text) returns void language plpgsql as $$begin
 begin execute command;exception when insufficient_privilege or check_violation or unique_violation then return;end;
 raise exception 'Expected rejected command: %',command;end;$$;
select public.b06_assert((select count(*)=2 from public.messages where conversation_id='__CID__'),'first contact canonical two messages');
select public.b06_assert((select count(*)=1 from marketplace_private.conversation_first_contacts where conversation_id='__CID__'),'first contact immutable receipt');
select public.b06_assert(not has_function_privilege('anon','public.marketplace_send_text(uuid,uuid,text)','execute'),'anon cannot send');
set role authenticated;set request.jwt.claim.role='authenticated';set request.jwt.claim.sub='11111111-1111-4111-8111-111111111111';
select public.b06_assert((public.marketplace_mark_conversation_read('__CID__',0)->>'unread_count')::int=1,'seller counts interest, excludes auto reply');
select public.marketplace_mark_conversation_read('__CID__',2);
set request.jwt.claim.sub='22222222-2222-4222-8222-222222222222';
select public.marketplace_send_text('__CID__','dddddddd-dddd-4ddd-8ddd-ddddddddddd1','  Buyer text  ');
set request.jwt.claim.sub='11111111-1111-4111-8111-111111111111';
select public.b06_assert((public.marketplace_mark_conversation_read('__CID__',1)->>'last_read_sequence')::int=2,'late read cannot regress watermark');
select public.b06_assert((public.marketplace_mark_conversation_read('__CID__',2)->>'unread_count')::int=1,'history boundary does not consume later message');
select public.marketplace_send_text('__CID__','dddddddd-dddd-4ddd-8ddd-ddddddddddd2','Seller reply');
set request.jwt.claim.sub='22222222-2222-4222-8222-222222222222';
select public.marketplace_send_text('__CID__','dddddddd-dddd-4ddd-8ddd-ddddddddddd1','Buyer text');
select public.b06_assert((public.marketplace_mark_conversation_read('__CID__',0)->>'unread_count')::int=1,'replayed send cannot clear later incoming unread');
select public.b06_reject($q$select public.marketplace_send_text('__CID__','dddddddd-dddd-4ddd-8ddd-ddddddddddd1','different payload')$q$);
select public.b06_reject($q$select public.marketplace_send_text('__CID__','dddddddd-dddd-4ddd-8ddd-ddddddddddd3','   ')$q$);
select public.b06_reject($q$select public.marketplace_mark_conversation_read('__CID__',9999)$q$);
select public.b06_assert((select count(*)=4 and max(sequence)=4 from public.messages where conversation_id='__CID__'),'rejected retries allocate no sequence');
set request.jwt.claim.sub='33333333-3333-4333-8333-333333333333';
select public.b06_assert((select count(*)=0 from public.messages where conversation_id='__CID__'),'outsider cannot read history');
select public.b06_assert((select count(*)=0 from public.conversations where id='__CID__'),'outsider cannot read conversation');
select public.b06_reject($q$select public.marketplace_send_text('__CID__','dddddddd-dddd-4ddd-8ddd-ddddddddddd3','forged')$q$);
select public.b06_reject($q$select public.marketplace_mark_conversation_read('__CID__',4)$q$);
set request.jwt.claim.sub='44444444-4444-4444-8444-444444444444';
select public.b06_reject($q$select public.marketplace_contact_seller('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2')$q$);
set request.jwt.claim.sub='11111111-1111-4111-8111-111111111111';
select public.b06_reject($q$select public.marketplace_contact_seller('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2')$q$);
set request.jwt.claim.sub='22222222-2222-4222-8222-222222222222';
select public.marketplace_prepare_image_message('__CID__','eeeeeeee-eeee-4eee-8eee-eeeeeeeeeee1','[{"original_name":"fixture.png","mime_type":"image/png","size_bytes":100,"sha256":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}]');
select public.marketplace_prepare_image_message('__CID__','eeeeeeee-eeee-4eee-8eee-eeeeeeeeeee1','[{"original_name":"fixture.png","mime_type":"image/png","size_bytes":100,"sha256":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}]');
select public.b06_assert((select count(*)=1 from public.image_message_submissions),'same UUID prepare one submission');
select public.b06_assert((select max(sequence)=4 from public.messages where conversation_id='__CID__'),'pending images not visible messages');
select public.b06_reject($q$select public.marketplace_finalize_image_message((select id from public.image_message_submissions))$q$);
select public.b06_reject($q$select public.marketplace_prepare_image_message('__CID__','eeeeeeee-eeee-4eee-8eee-eeeeeeeeeee1','[{"original_name":"changed.png","mime_type":"image/png","size_bytes":100,"sha256":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}]')$q$);
reset role;
insert into storage.objects(bucket_id,name,metadata) select 'chat-images',m->>'storage_path','{"mimetype":"image/png","size":100}' from public.image_message_submissions s cross join lateral jsonb_array_elements(s.manifest) m;
-- Trusted Storage fixture supplies receipt arguments; runtime caller role is separately ACL-checked.
set request.jwt.claim.role='service_role';
select public.marketplace_record_verified_chat_image(s.id,(m->>'id')::uuid,s.sender_id,o.id,m->>'sha256') from public.image_message_submissions s cross join lateral jsonb_array_elements(s.manifest) m join storage.objects o on o.name=m->>'storage_path' and o.bucket_id='chat-images';
reset role;set role authenticated;set request.jwt.claim.role='authenticated';set request.jwt.claim.sub='22222222-2222-4222-8222-222222222222';
select public.marketplace_finalize_image_message((select id from public.image_message_submissions));
select public.marketplace_finalize_image_message((select id from public.image_message_submissions));
select public.b06_assert((select count(*)=1 from public.messages where type='IMAGE'),'finalize retry one image message');
select public.b06_assert((select count(*)=1 from public.message_images),'one canonical attachment');
select public.b06_assert((select max(sequence)=5 from public.messages where conversation_id='__CID__'),'image consumes one sequence');
select public.b06_reject($q$select public.marketplace_abandon_image_message((select id from public.image_message_submissions))$q$);
set request.jwt.claim.sub='11111111-1111-4111-8111-111111111111';
select public.b06_assert((select count(*)=1 from public.message_images),'recipient reads attachment metadata');
select public.b06_assert((select count(*)=0 from public.image_message_submissions),'recipient cannot read sender pending lifecycle');
select public.b06_assert((select count(*)=0 from storage.objects where bucket_id='chat-images'),'no direct authenticated private Storage read');
set request.jwt.claim.sub='33333333-3333-4333-8333-333333333333';
select public.b06_assert((select count(*)=0 from public.message_images),'outsider cannot obtain signing metadata');
-- Cancelled image never allocates a sent sequence, and durable cleanup remains.
set request.jwt.claim.sub='22222222-2222-4222-8222-222222222222';
select public.marketplace_prepare_image_message('__CID__','eeeeeeee-eeee-4eee-8eee-eeeeeeeeeee2','[{"original_name":"cancel.png","mime_type":"image/png","size_bytes":100,"sha256":"bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb"}]');
select public.marketplace_abandon_image_message((select id from public.image_message_submissions where state='pending'));
select public.marketplace_abandon_image_message((select id from public.image_message_submissions where state='abandoned'));
select public.b06_reject($q$select public.marketplace_finalize_image_message((select id from public.image_message_submissions where state='abandoned'))$q$);
reset role;
select public.b06_assert((select count(*)=1 from marketplace_private.chat_image_cleanup),'abandoned upload retains cleanup tombstone');
-- Existing private Broadcast policies, with a deliberately broad local platform policy.
create policy b06_platform_read on realtime.messages for select using(true);
set role authenticated;set request.jwt.claim.role='authenticated';set request.jwt.claim.sub='22222222-2222-4222-8222-222222222222';
set realtime.topic='marketplace:messages:22222222-2222-4222-8222-222222222222';
select public.b06_assert((select count(*)>0 from realtime.messages),'own private topic readable');
select public.b06_assert(not exists(select 1 from realtime.messages where topic<>'marketplace:messages:22222222-2222-4222-8222-222222222222'),'private topic fence');
set request.jwt.claim.sub='33333333-3333-4333-8333-333333333333';
select public.b06_assert((select count(*)=0 from realtime.messages),'outsider cannot subscribe to another private topic');
reset role;
select public.b06_assert(not exists(select 1 from realtime.messages where payload ? 'content' or payload ? 'accessToken' or private is distinct from true),'broadcast minimal invalidations, no content/token');
-- Optional Broadcast outage must not roll back durable sends.
create or replace function realtime.send(jsonb,text,text,boolean) returns void language plpgsql as $$begin raise exception 'local simulated outage';end;$$;
set role authenticated;set request.jwt.claim.sub='11111111-1111-4111-8111-111111111111';
update public.listings set status='sold' where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1';
set request.jwt.claim.sub='22222222-2222-4222-8222-222222222222';
select public.marketplace_contact_seller('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1');
select public.marketplace_send_text('__CID__','dddddddd-dddd-4ddd-8ddd-ddddddddddd4','Sold thread still usable');
set request.jwt.claim.sub='11111111-1111-4111-8111-111111111111';
delete from public.listings where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1';
set request.jwt.claim.sub='22222222-2222-4222-8222-222222222222';
select public.b06_assert((select listing_id is null from public.conversations where id='__CID__'),'deleted listing retains conversation identity');
select public.marketplace_send_text('__CID__','dddddddd-dddd-4ddd-8ddd-ddddddddddd5','Deleted thread still usable');
select public.b06_assert((select max(sequence)=7 from public.messages where conversation_id='__CID__'),'durable sends survive optional Broadcast outage and Listing deletion');
reset role;
